{
  "药物": [
    {
      "名称": "速尿",
      "详细描述": "用于促进肺水肿的消退，剂量为40～60mg，分2～3次静脉注射。"
    },
    {
      "名称": "氢化可的松",
      "详细描述": "用于减轻肺泡一毛细血管膜损伤，缓解支气管痉挛，抗炎和促进肺水肿的吸收。常用剂量为每日200～300mg，静脉注射。主要用于刺激性气体、脂肪栓塞、内毒素所致的早期ARDS。使用宜尽早、大剂量、短期。"
    },
    {
      "名称": "地塞米松",
      "详细描述": "用于减轻肺泡一毛细血管膜损伤，缓解支气管痉挛，抗炎和促进肺水肿的吸收。常用剂量为20～30mg静脉注射，每日3次，连用2天，若有效则1周内开始减量，无效应及早停用。主要用于刺激性气体、脂肪栓塞、内毒素所致的早期ARDS。"
    },
    {
      "名称": "白蛋白",
      "详细描述": "用于渗透压很低的患者，作为胶体溶液以维持适当的渗透压。"
    },
    {
      "名称": "血浆",
      "详细描述": "用于渗透压很低的患者，作为胶体溶液以维持适当的渗透压。"
    }
  ],
  "治疗手段": [
    {
      "名称": "氧疗",
      "详细描述": "呼吸空气时动脉血氧分压(PaO2)小于8kPa者应作氧疗。短期内可使用较高浓度给氧，吸入氧浓度(FiO2)达60%左右。常用鼻导管或鼻塞法供氧，若难以奏效，可采用氧疗面罩(Venturi)或持续气道正压呼吸(CPAP)。长期高浓度氧吸入可能引起氧中毒，应在保持适当PaO2(≥8kPa)前提下，尽量降低FiO2值，通常FiO2<60%较为安全。"
    },
    {
      "名称": "持续气道正压呼吸(CPAP)",
      "详细描述": "通过储气袋供氧，呼出气经由水封瓶排出，呼出管插入水封瓶的深度即为呼气末正压值。这种方法给氧可防止肺泡萎陷，减少静动脉分流，改善v/Q比值。"
    },
    {
      "名称": "机械通气",
      "详细描述": "间歇正压通气可替代自主呼吸、减少呼吸功、缓解呼吸困难症状，但不能防止呼气末肺泡的萎陷。目前多采用呼吸末正压通气(PEEP)，可显著提高疗效。PEEP在整个呼吸过程中保持正压，增加功能残气量、使萎陷的肺泡复张、减轻肺间质水肿、改善通气/血流比例失调，减少肺内分流。应用PEEP时需确定最适宜的PEEP值，一般开始时以0.29～0.49kPa(3～5cmH2O)为宜，逐步增加到0.98kPa(10cmH2O)，最高不超过1.47kPa(15cmH2O)。病情稳定后逐步降低PEEP值。"
    },
    {
      "名称": "严格掌握补液",
      "详细描述": "ARDS由于肺间质和肺泡水肿，肺含水量增加，输液过多可加重肺水肿。在维持血压稳定的前提下，保持液体轻度负平衡，每日输液量不超过1500～2000ml，尽量给予晶体溶液。有条件者可作血流动力学监测，包括通过Swan-Ganz肺动脉导管监测肺动脉楔压(维持在0.667～1.33kPa，即5～10mmHg)。"
    }
  ]
}

